29	class ResumeDriver
30	{
31	public:
32	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
33	  // dmcontrol/dmstatus are run-control registers specific to this driver.
34	  static constexpr uint8_t kData0      = kDmiData0;
35	  static constexpr uint8_t kData1      = kDmiData1;
36	  static constexpr uint8_t kDmcontrol  = 0x10;
37	  static constexpr uint8_t kDmstatus   = 0x11;
38	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
39	  static constexpr uint8_t kCommand    = kDmiCommand;
40	
41	  static constexpr uint16_t kCsrDpc      = 0x7B1;
42	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
43	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
44	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
45	  static constexpr uint16_t kCsrFcsr     = 0x003;
46	  static constexpr uint16_t kCsrMstatus  = 0x300;
47	  static constexpr uint16_t kCsrMisa     = 0x301;
48	  static constexpr uint16_t kCsrMedeleg  = 0x302;
49	  static constexpr uint16_t kCsrMideleg  = 0x303;
50	  static constexpr uint16_t kCsrMie      = 0x304;
51	  static constexpr uint16_t kCsrMtvec    = 0x305;
52	  static constexpr uint16_t kCsrMscratch = 0x340;
53	  static constexpr uint16_t kCsrMepc     = 0x341;
54	  static constexpr uint16_t kCsrMcause   = 0x342;
55	  static constexpr uint16_t kCsrMtval    = 0x343;
56	  static constexpr uint16_t kCsrMip      = 0x344;
57	  static constexpr uint16_t kCsrSatp     = 0x180;
58	  static constexpr uint16_t kCsrMcycle   = 0xB00;
59	  static constexpr uint16_t kCsrMinstret = 0xB02;
60	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
61	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
62	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
63	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
64	  static constexpr uint16_t kCsrVlenb    = 0xC22;
65	  static constexpr uint16_t kCsrVstart   = 0x008;
66	  static constexpr uint16_t kCsrVxsat    = 0x009;
67	  static constexpr uint16_t kCsrVxrm     = 0x00A;
68	  static constexpr uint16_t kCsrVcsr     = 0x00F;
69	  static constexpr uint16_t kCsrVtype    = 0xC21;
70	  static constexpr uint16_t kCsrVl       = 0xC20;
71	
72	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
73	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
74	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
75	
76	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
77	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
78	
79	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
80	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
81	
82	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
83	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
84	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
85	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
86	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
87	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
88	
89	  static constexpr unsigned kPollIterations = kDmiPollIterations;
90	
91	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
92	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
93	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
94	  // GPA still unset throws in the sweep (no silent transport via a bogus
95	  // address). The simulator passes the real value from platform.main_memory.
96	  // caps: which Andes custom CSRs the TARGET core implements (derived from its
97	  // config.inc, supplied by the sim binary). Defaults to all() -- transport
98	  // every CSR, the prior behavior -- so existing call sites are unchanged.
99	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
100	                        AndesCaps caps = AndesCaps::all())
101	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
102	  {}
103	
104	  // Opt-in GPR block-load (prototype): reload x1..x31 with a Program-Buffer
105	  // ld-sweep from the scratch page instead of 31 abstract register writes.
106	  // Off by default so existing callers/tests are unchanged; the simulator
107	  // enables it and stages the values via stage_gpr_to_scratch.
108	  void set_gpr_block_load(bool on) { gpr_block_load_ = on; }
109	
110	  // Opt-in FPR block-load (prototype): reload f0..f31 with a Program-Buffer
111	  // fld-sweep from the scratch page instead of 32 abstract register writes.
112	  // Off by default so existing callers/tests are unchanged; the simulator
113	  // enables it and stages the values via stage_fpr_to_scratch.
114	  void set_fpr_block_load(bool on) { fpr_block_load_ = on; }
115	
116	  // LG1/LG2 (liveness gate): supply the engine's own reset-state drain.
117	  // Restores whose drained value equals this baseline are skipped -- the
118	  // write would be a no-op, and every DM operation costs hundreds of
119	  // simulated cycles. LG1 gates each tolerant CSR write; LG2 elides the FPR
120	  // and V data blocks as whole blocks when byte-equal. Unset (default) keeps
121	  // transport-everything. Always-live state (mstatus, GPRs, dpc, dcsr,
122	  // mcycle, minstret, the S/U PMP mirror) is never gated.
123	  //
124	  // v_cfg_at_reset: pass false when the baseline was CAPTURED this run --
125	  // the capture drain's V dump sweep already clobbered the hart's
126	  // vtype/vl/vstart, so their baseline equality no longer proves the
127	  // architectural vsetvl redundant. Cache-hit runs (pristine hart) pass true.
128	  void set_reset_baseline(const hybrid_state_v1& b, bool v_cfg_at_reset = true)
129	  {
130	    baseline_ = b;
131	    has_baseline_ = true;
132	    v_cfg_at_reset_ = v_cfg_at_reset;
133	  }
134	
135	  // Number of register-restore operations elided by the reset baseline this
136	  // resume: one per gated CSR write, 32 per elided FPR/V data block, one per
137	  // elided vsetvl.
138	  auto baseline_skip_count() const -> uint64_t { return baseline_skip_count_; }
139	
140	  void resume(const hybrid_state_v1& state)
141	  {
142	    if (state.magic != HYBRID_STATE_MAGIC)
143	      throw std::runtime_error("ResumeDriver::resume: bad magic");
144	    if (state.version != HYBRID_STATE_VERSION)
145	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
146	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
147	    if (state.priv == 2 || state.priv > 3)
148	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
149	
150	    // dmactive must transition 0->1 in its own write before any other
151	    // DMCONTROL bit is honored (RISC-V Debug Spec).
152	    bus_.write(kDmcontrol, kDmcontrolDmactive);
153	    request_halt();
154	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
155	
156	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
157	    // accepted (FS or VS == Off disables the extension and the hart NACKs
158	    // the writes). The drained state.mstatus may legitimately carry FS or
159	    // VS at Off (e.g. an OS context-switched the regs away before the
160	    // trigger fired) -- gating the write on the drained field skips the
161	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
162	    // write mstatus when either extension is in scope; force-OR Initial
163	    // when the drained field is Off. This enable is local to the vsim
164	    // phase; the state.mstatus written to the handoff file is left
165	    // unmodified.
166	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
167	      uint64_t enable_mstatus = state.mstatus;
168	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
169	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
170	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
171	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
172	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
173	    }
174	
175	    // FPR restore (requires mstatus.FS enabled above). The block-load (opt-in)
176	    // sweeps f0..f31 from the scratch page via a PB fld-sweep -- ~6 halted-hart
177	    // round-trips instead of 32 abstract writes -- when the V region leaves room;
178	    // otherwise fall back to per-register abstract writes. Its integer base x5 is
179	    // re-staged by the V sweep and restored by the GPR loop below, so it is safe
180	    // to clobber here.
181	    if (state.flags & HYBRID_FLAG_FP) {
182	      // LG2: elide the whole FPR block when every f-reg already holds the
183	      // engine's reset value -- the reload would rewrite what is there.
184	      const bool fpr_equal = has_baseline_
185	        && std::memcmp(state.fpr, baseline_.fpr, sizeof state.fpr) == 0;
186	      if (fpr_equal) {
187	        baseline_skip_count_ += 32;
188	      } else if (fpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
189	                 && fpr_scratch_fits(state.vlenb)) {
190	        restore_fprs_via_pb(fpr_scratch_gpa(scratch_gpa_));
191	      } else {
192	        for (uint16_t i = 0; i < 32; ++i)
193	          write_64bit_register(regno_fpr(i), state.fpr[i]);
194	      }
195	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
196	      // fallback scratch x5 is overwritten by the GPR loop below.
197	      if (!baseline_skips(state.fcsr, baseline_.fcsr))
198	        write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
199	    }
200	
201	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
202	    // the GPR loop overwrites x5 afterward so state is preserved).
203	    if (state.flags & HYBRID_FLAG_V) {
204	      // V data regfile: reload v0..v31 from the shared scratch region via the
205	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
206	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
207	      // the restore then overwrites with the architectural values. The sweep
208	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
209	      // below restores all three. The scratch is vlenb-packed
210	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
211	      if (scratch_gpa_ == kVScratchGpaUnset)
212	        throw std::runtime_error(
213	          "ResumeDriver::resume: V state present but scratch GPA unset");
214	      // LG2: elide the reload sweep when every v-reg already holds the
215	      // engine's reset bytes.
216	      const bool v_data_equal = has_baseline_
217	        && std::memcmp(state.vreg, baseline_.vreg, sizeof state.vreg) == 0;
218	      if (v_data_equal)
219	        baseline_skip_count_ += 32;
220	      else
221	        pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
222	
223	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
224	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
225	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
226	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
227	      // LG2 clobber rule: the data sweep's own vsetvl overwrote vtype/vl/
228	      // vstart, so baseline equality only proves this vsetvl redundant when
229	      // the sweep did NOT run.
230	      const bool vcfg_equal = v_data_equal && v_cfg_at_reset_
231	        && state.vl == baseline_.vl && state.vtype == baseline_.vtype;
232	      if (vcfg_equal) {
233	        ++baseline_skip_count_;  // the elided vsetvl exec
234	      } else {
235	        write_64bit_register(regno_gpr(5), state.vl);
236	        write_64bit_register(regno_gpr(6), state.vtype);
237	        const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
238	        exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
239	      }
240	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0 -- so its
241	      // baseline skip is likewise only valid when no vsetvl executed.
242	      if (!(vcfg_equal && baseline_skips(state.vstart, baseline_.vstart)))
243	        write_csr_abstract_or_pb(kCsrVstart, state.vstart);
244	      if (!baseline_skips(state.vxsat, baseline_.vxsat))
245	        write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
246	      if (!baseline_skips(state.vxrm, baseline_.vxrm))
247	        write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
248	      if (!baseline_skips(state.vcsr, baseline_.vcsr))
249	        write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
250	    }
251	
252	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
253	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
254	    // in the drained privilege; M-mode states skip the write (prv already 3).
255	    // Before the GPR loop: a PB fallback would clobber scratch x5.
256	    if (state.priv != 3) {
257	      // L2 slice: with PMP implemented and no matching entry, every S/U
258	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
259	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
260	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
261	      // RV64. Tolerant writes: entries beyond what the hart implements
262	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
263	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
264	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
265	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
266	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
267	
268	      const uint64_t dcsr =
269	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
270	      write_csr_abstract_or_pb(kCsrDcsr,
271	                               (dcsr & ~uint64_t{0x3}) | state.priv);
272	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
273	      // silently measure the ROI in the wrong privilege. Verify and abort.
274	      const uint64_t got =
275	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
276	        & 0x3u;
277	      if (got != state.priv)
278	        throw std::runtime_error(
279	          "ResumeDriver::resume: engine does not implement privilege level "
280	          + std::to_string(state.priv)
281	          + " (dcsr.prv pinned to " + std::to_string(got)
282	          + "); pick an S/U-capable engine");
283	    }
284	
285	    // Andes V5 + M-ext CSR restore (abstract-only, LG1-gated). See
286	    // restore_andes_m_ext.
287	    restore_andes_m_ext(state);
288	
289	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite). The
290	    // block-load (opt-in) sweeps x1..x31 from the scratch page via the Program
291	    // Buffer -- ~4 DM round-trips instead of 31 abstract writes -- when the V
292	    // region leaves room; otherwise fall back to per-register abstract writes.
293	    if (gpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
294	        && gpr_scratch_fits(state.vlenb)) {
295	      restore_gprs_via_pb(gpr_scratch_gpa(scratch_gpa_));
296	    } else {
297	      for (uint16_t i = 1; i < 32; ++i)
298	        write_64bit_register(regno_gpr(i), state.gpr[i]);
299	    }
300	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
301	
302	    write_csr_tolerant_gated(kCsrMtvec, state.mtvec, baseline_.mtvec);
303	
304	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
305	    // register with no hardware side effects, legal to use inside a trap-free
306	    // ROI. Restore it so a value stashed before the handoff survives into the
307	    // vsim phase.
308	    write_csr_tolerant_gated(kCsrMscratch, state.mscratch, baseline_.mscratch);
309	
310	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
311	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
312	    // value stashed before the handoff must survive into the vsim phase (same
313	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
314	    // hardware-driven pending bits, or mtval on a core that hardwires it)
315	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
316	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
317	    write_csr_tolerant_gated(kCsrMepc,   state.mepc,   baseline_.mepc);
318	    write_csr_tolerant_gated(kCsrMcause, state.mcause, baseline_.mcause);
319	    write_csr_tolerant_gated(kCsrMtval,  state.mtval,  baseline_.mtval);
320	    write_csr_tolerant_gated(kCsrMie,    state.mie,    baseline_.mie);
321	    write_csr_tolerant_gated(kCsrMip,    state.mip,    baseline_.mip);
322	
323	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
324	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
325	    // caches) but has no cache model, so without this the cycle engine resumes
326	    // at the ROI with caches at their reset default -- DISABLED -- and the
327	    // whole measured window runs uncached, inflating it severalfold. Tolerant
328	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
329	    // write as a no-op, and a drained 0 (caches were off) restores the reset
330	    // state, so this is always safe to issue.
331	    write_csr_tolerant_gated(kCsrMcacheCtl, state.mcache_ctl,
332	                             baseline_.mcache_ctl);
333	    write_csr_tolerant_gated(kCsrMmiscCtl,  state.mmisc_ctl,
334	                             baseline_.mmisc_ctl);
335	
336	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
337	    // from QEMU1's drain value. Without this, vsim's local counter starts
338	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
339	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
340	    // overwrite here as the GPR loop already ran.
341	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
342	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
343	
344	    clear_cmderr_if_set();
345	    request_resume();
346	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
347	                   "ResumeDriver resume");
348	  }
349	
350	private:
351	  void request_halt()
352	  {
353	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
354	  }
355	
356	  void request_resume()
357	  {
358	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
359	  }
360	
361	  void write_64bit_register(uint16_t regno, uint64_t value)
362	  {
363	    write_register_abstract(bus_, regno, value);
364	  }
365	
366	  // GPR block-load: reload x1..x31 from the scratch page via a PB ld-sweep. Base
367	  // x31 rides the sweep last (it is the base pointer). x31's slot is the
368	  // mapping's final word, which the memory decoder now returns correctly.
369	  void restore_gprs_via_pb(uint64_t gpr_gpa)
370	  {
371	    pb_block_sweep(bus_, 31, gpr_gpa, 1, 32, &encode_ld);
372	  }
373	
374	  // FPR block-load: reload f0..f31 from the scratch page via a PB fld-sweep,
375	  // integer base x5 (a caller-saved scratch the GPR loop restores later). No
376	  // f-reg is the base, so all 32 ride the sweep (first_reg = 0).
377	  void restore_fprs_via_pb(uint64_t fpr_gpa)
378	  {
379	    pb_block_sweep(bus_, 5, fpr_gpa, 0, 32, &encode_fld);
380	  }
381	
382	  // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR
383	  // (pmaaddr before pmacfg, mirroring the PMP restore ordering), each gated by
384	  // the LG1 reset baseline. Abstract-only by design -- a batched Program-Buffer
385	  // sweep can't tolerate a cmderr on one CSR without corrupting the rest of the
386	  // batch (a WARL/read-only CSR faults the whole group mid-sweep), whereas the
387	  // per-CSR abstract path tolerates a single failure and moves on.
388	  void restore_andes_m_ext(const hybrid_state_v1& state)
389	  {
390	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
391	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
392	    if (!andes && !mext) return;
393	
394	    if (andes) {
395	#define X(field, addr, name)     \
396	  if (caps_.supports_csr(addr))  \
397	    write_csr_tolerant_gated(addr, state.andes.field, baseline_.andes.field);
398	      HYBRID_ANDES_CSR_LIST(X)
399	#undef X
400	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
401	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
402	          write_csr_tolerant_gated(HYBRID_PMA_ADDR0_CSR + i,
403	                                   state.andes.pmaaddr[i],
404	                                   baseline_.andes.pmaaddr[i]);
405	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
406	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
407	          write_csr_tolerant_gated(HYBRID_PMA_CFG0_CSR + 2 * i,
408	                                   state.andes.pmacfg[i],
409	                                   baseline_.andes.pmacfg[i]);
410	    }
411	    if (mext) {
412	#define X(field, addr, name)     \
413	  if (caps_.supports_csr(addr))  \
414	    write_csr_tolerant_gated(addr, state.m_ext.field, baseline_.m_ext.field);
415	      HYBRID_M_EXT_CSR_LIST(X)
416	#undef X
417	    }
418	  }
419	
420	  // Abstract-first CSR write with Program Buffer fallback.
421	  // Tries an abstract register write; if the DM signals cmderr, clears it,
422	  // stages the value in scratch_gpr via abstract GPR write, then executes a
423	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
424	  // to x5 (t0) which the GPR restore loop overwrites later.
425	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
426	                                 uint8_t scratch_gpr = 5)
427	  {
428	    write_64bit_register(regno_csr(csr), value);
429	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
430	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
431	    write_64bit_register(regno_gpr(scratch_gpr), value);
432	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
433	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
434	  }
435	
436	  // Write a CSR-addressable register and clear any cmderr the DM raised.
437	  // Used for CSRs whose abstract-access support may be implementation
438	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
439	  // remaining writes.
440	  void write_csr_tolerant(uint16_t csr, uint64_t value)
441	  {
442	    write_64bit_register(regno_csr(csr), value);
443	    clear_cmderr_if_set();
444	  }
445	
446	  // LG1: true (and counted) when the reset baseline marks this write a no-op.
447	  auto baseline_skips(uint64_t value, uint64_t reset_value) -> bool
448	  {
449	    if (!has_baseline_ || value != reset_value) return false;
450	    ++baseline_skip_count_;
451	    return true;
452	  }
453	
454	  // Tolerant CSR write elided when the value already equals the engine's
455	  // reset value (reset_value is only meaningful when the baseline is set;
456	  // baseline_ is zero-initialized otherwise and baseline_skips ignores it).
457	  void write_csr_tolerant_gated(uint16_t csr, uint64_t value,
458	                                uint64_t reset_value)
459	  {
460	    if (baseline_skips(value, reset_value)) return;
461	    write_csr_tolerant(csr, value);
462	  }
463	
464	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
465	  // is rejected until the bits are W1C-cleared. We tolerate per-register
466	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
467	  // error before resuming so the hart isn't left in a stuck state.
468	  // B17: record the last observed non-zero cmderr and a clear count so a
469	  // partially-broken restore is observable via the public accessors
470	  // instead of silently swallowed.
471	  void clear_cmderr_if_set()
472	  {
473	    const auto status = bus_.read(kAbstractcs);
474	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
475	    if (code != 0u) {
476	      last_observed_cmderr_ = code;
477	      ++cmderr_clear_count_;
478	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
479	    }
480	  }
481	
482	  DmiBus& bus_;
483	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
484	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
485	  bool gpr_block_load_ = false;               // opt-in GPR PB ld-sweep
486	  bool fpr_block_load_ = false;               // opt-in FPR PB fld-sweep
487	  hybrid_state_v1 baseline_{};                // LG1: engine reset-state drain
488	  bool has_baseline_ = false;                 // baseline_ valid only when set
489	  bool v_cfg_at_reset_ = true;                // false: capture clobbered vcfg
490	  uint64_t baseline_skip_count_ = 0;          // LG1: elided tolerant writes
491	  uint32_t last_observed_cmderr_ = 0;
492	  uint64_t cmderr_clear_count_   = 0;
493	
494	public:
495	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
496	  // at least one abstract write tripped a sticky cmderr the restore
497	  // tolerated by clearing. cmderr_clear_count() is the total number of
498	  // such clears across all calls into clear_cmderr_if_set() this run.
499	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
500	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
501	};
502	
503	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
504	// via an Abstract Command. Halts-and-reads contract: caller must have the
505	// hart in the halted state. Shared by StateDrain (drain at exit). If
506	// abstractcs.cmderr goes sticky after the command, the helper clears it and
507	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
508	// instead of corrupting the adjacent field.
509	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
510	                                     const char* poll_label
511	                                       = "read_register_64")
512	  -> std::optional<uint64_t>
513	{
514	  using RD = ResumeDriver;
515	  bus.write(RD::kCommand,
516	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
517	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
518	  const auto status = bus.read(RD::kAbstractcs);
519	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
520	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
521	    return std::nullopt;
522	  }
523	  const uint64_t lo = bus.read(RD::kData0);
524	  const uint64_t hi = bus.read(RD::kData1);
525	  return lo | (hi << 32);
526	}
527	
528	inline auto read_register_64(DmiBus& bus, uint16_t regno,
529	                             const char* poll_label = "read_register_64")
530	  -> uint64_t
531	{
532	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
533	}
534	
535	}  // namespace hybrid
