1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/andes_caps.hpp"
9	#include "hybrid/dmi_poll.hpp"
10	#include "hybrid/resume_driver.hpp"
11	#include "hybrid/state_abi.h"
12	#include "hybrid/v_regfile_xfer.hpp"
13	
14	#include <algorithm>
15	#include <array>
16	#include <cstdint>
17	#include <span>
18	
19	namespace hybrid
20	{
21	
22	class StateDrain
23	{
24	public:
25	  using RD = ResumeDriver;
26	
27	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
28	  // the mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the
29	  // unset sentinel; only the V dump sweep consults it, and it throws there if
30	  // a V drain is reached with the GPA unset (no silent dump to a bogus
31	  // address). The simulator passes the real value from platform.main_memory.
32	  // caps: which Andes custom CSRs the TARGET core implements (from its
33	  // config.inc, supplied by the sim binary). Defaults to all() so existing
34	  // call sites are unchanged. Gates the Andes re-read below: reading an
35	  // unimplemented CSR can stall the DM, same as restoring one.
36	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
37	                      AndesCaps caps = AndesCaps::all())
38	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
39	  {}
40	
41	  // Opt-in PB block-store (dual of ResumeDriver's set_gpr/fpr_block_load):
42	  // drain the GPRs/FPRs with a sd/fsd-sweep into the shared scratch page instead
43	  // of per-register Abstract Command reads. Default OFF; the simulator enables
44	  // both and lifts the swept bytes with read_{gpr,fpr}_from_scratch. Each is
45	  // fits-gated in drain_with_passthrough so a full V page falls back to reads.
46	  void set_gpr_block_store(bool on) { gpr_block_store_ = on; }
47	  void set_fpr_block_store(bool on) { fpr_block_store_ = on; }
48	
49	  // Opt-in Andes+M-ext CSR sweep (dual of ResumeDriver::set_csr_sweep): drain
50	  // the caps-supported CSR block with a Program-Buffer csrr+sd sweep into the CSR
51	  // scratch page instead of one abstract read per CSR. Off by default; the
52	  // simulator enables it and lifts the swept values with read_csr_from_scratch.
53	  void set_csr_sweep(bool on) { csr_sweep_ = on; }
54	
55	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
56	  // drain_with_passthrough when the QEMU 1 snapshot is available.
57	  auto drain() -> hybrid_state_v1
58	  {
59	    hybrid_state_v1 state{};
60	    state.magic   = HYBRID_STATE_MAGIC;
61	    state.version = HYBRID_STATE_VERSION;
62	    state.flags   = HYBRID_FLAG_RV64;
63	    halt_and_capture_pc_priv(state);
64	
65	    for (uint16_t i = 1; i < 32; ++i)
66	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
67	
68	    return state;
69	  }
70	
71	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
72	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
73	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
74	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
75	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
76	  // and vreg remain pass-through (read-only / too large for DM).
77	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
78	  // contribution would otherwise be discarded as the passthrough preserves
79	  // QEMU1's pre-handoff value.
80	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
81	  {
82	    auto state = input;
83	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
84	
85	    // GPRs: the dual of the resume block-load. When enabled and the V region
86	    // leaves room (same fits-gate as the resume side), sd-sweep x1..x30 from the
87	    // regfile into the scratch page in ~6 round-trips instead of 31 abstract
88	    // reads; the simulator lifts them with read_gpr_from_scratch. Base x31 is the
89	    // sweep's pointer -- seeding it destroys its value -- so it is captured here
90	    // via one abstract read and excluded from the sweep.
91	    if (gpr_block_store_ && scratch_gpa_ != kVScratchGpaUnset
92	        && gpr_scratch_fits(input.vlenb)) {
93	      state.gpr[31] =
94	        read_register_64(bus_, regno_gpr(31), "StateDrain GPR base");
95	      pb_block_sweep(bus_, 31, gpr_scratch_gpa(scratch_gpa_), 1, 31, &encode_sd);
96	    } else {
97	      for (uint16_t i = 1; i < 32; ++i)
98	        state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
99	    }
100	
101	    if (input.flags & HYBRID_FLAG_FP) {
102	      // FPRs: fsd-sweep into the scratch page (below the GPR block) when enabled
103	      // and fits; the simulator lifts f0..f31 with read_fpr_from_scratch. Base x5
104	      // is a caller-saved GPR already captured above (via the GPR abstract loop
105	      // or the GPR sweep's scratch), so clobbering it here is safe -- the hart is
106	      // terminal after drain.
107	      if (fpr_block_store_ && scratch_gpa_ != kVScratchGpaUnset
108	          && fpr_scratch_fits(input.vlenb)) {
109	        pb_block_sweep(bus_, 5, fpr_scratch_gpa(scratch_gpa_), 0, 32, &encode_fsd);
110	      } else {
111	        for (uint16_t i = 0; i < 32; ++i)
112	          state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
113	      }
114	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
115	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
116	    }
117	
118	    if (input.flags & HYBRID_FLAG_V) {
119	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
120	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
121	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
122	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
123	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
124	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
125	    }
126	
127	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
128	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
129	    // dropped and the stale QEMU1 value passes through into the drained state.
130	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
131	
132	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
133	    // restores them), so re-read them -- an in-ROI write must reach the drained
134	    // state instead of the stale QEMU1 passthrough value.
135	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
136	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
137	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
138	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
139	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
140	
141	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
142	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
143	
144	    // Andes V5 + M-ext CSR block (v3/v4): re-read the transported CSRs so an
145	    // in-ROI write reaches the drained state instead of the stale QEMU1
146	    // passthrough (same round-trip as mscratch). When the csr_sweep is enabled
147	    // this rides a PB csrr+sd sweep into the CSR scratch page (the simulator
148	    // lifts it via read_csr_from_scratch); else one caps-gated abstract read per
149	    // CSR. See drain_andes_m_ext.
150	    drain_andes_m_ext(state);
151	
152	    // V data regfile: dump v0..v31 to the shared scratch region via the
153	    // Program Buffer LAST -- after every architectural read above -- so the
154	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
155	    // cannot corrupt the values already captured. The simulator's
156	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
157	    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
158	    if (input.flags & HYBRID_FLAG_V)
159	      dump_v_to_scratch(input.vlenb);
160	
161	    return state;
162	  }
163	
164	  // #1 (drain-minimal): refresh only mcycle/minstret from the hart and pass
165	  // every other field through from the QEMU1 snapshot. Used when --verify is
166	  // off: the driver then consumes only the vsim mcycle delta, so the full
167	  // register-file readback drain_with_passthrough performs (~190 DMI abstract
168	  // commands -- f0..f31, the V dump sweep, the Andes/M-ext blocks, ...) is pure
169	  // wasted wall-clock. The hart is left halted, identical to the full drain, so
170	  // the caller's file-write + exit path is unchanged.
171	  auto drain_counters_only(const hybrid_state_v1& input) -> hybrid_state_v1
172	  {
173	    halt("StateDrain halt (minimal)");
174	
175	    auto state     = input;
176	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle),
177	                                      "StateDrain mcycle");
178	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret),
179	                                      "StateDrain minstret");
180	    return state;
181	  }
182	
183	private:
184	  // Debug-Module halt-and-wait, shared by drain() and drain_counters_only():
185	  // dmactive must transition 0->1 in its own write before haltreq is honored
186	  // (RISC-V Debug Spec), then wait for allhalted. `ctx` labels the poll.
187	  void halt(const char* ctx)
188	  {
189	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
190	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
191	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted, ctx);
192	  }
193	
194	  // Halt the hart and capture the two control fields every drain path needs:
195	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
196	  // blocks are filled by the caller, so drain() and drain_with_passthrough
197	  // share one halt + prologue.
198	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
199	  {
200	    halt("StateDrain halt");
201	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
202	                                  "StateDrain DCSR") & 0x3u;
203	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
204	  }
205	
206	  // Andes V5 + M-ext CSR drain. When the sweep is enabled and the V region
207	  // leaves room, batch every caps-supported CSR into the CSR scratch page via a
208	  // PB csrr+sd sweep (base x6 / value x5 -- both already captured by the GPR
209	  // drain above, and the hart is terminal, so clobbering them is safe); the
210	  // simulator lifts the bytes with read_csr_from_scratch. Else one caps-gated
211	  // abstract read per CSR into state. Same for_each_sweep_csr order + caps gate
212	  // as the ResumeDriver restore, so the scratch slots agree.
213	  void drain_andes_m_ext(hybrid_state_v1& state)
214	  {
215	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
216	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
217	    if (!andes && !mext) return;
218	
219	    if (csr_sweep_ && scratch_gpa_ != kVScratchGpaUnset
220	        && csr_scratch_fits(state.vlenb)) {
221	      std::array<uint16_t, kCsrScratchSlots> addrs{};
222	      std::size_t n = 0;
223	      for_each_sweep_csr(state, caps_,
224	        [&](std::size_t i, uint16_t addr, uint64_t&) { addrs[i] = addr; n = i + 1; });
225	      csr_sweep(bus_, /*base=*/6, csr_scratch_gpa(scratch_gpa_), /*val=*/5,
226	                std::span<const uint16_t>{addrs.data(), n}, CsrSweepDir::Drain);
227	      return;
228	    }
229	
230	    // Fallback: one caps-gated abstract read per CSR into state.
231	    if (andes) {
232	#define X(field, addr, name) \
233	  if (caps_.supports_csr(addr)) \
234	    state.andes.field = read_register_64(bus_, regno_csr(addr));
235	      HYBRID_ANDES_CSR_LIST(X)
236	#undef X
237	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
238	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
239	          state.andes.pmacfg[i] =
240	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
241	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
242	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
243	          state.andes.pmaaddr[i] =
244	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
245	    }
246	    if (mext) {
247	#define X(field, addr, name) \
248	  if (caps_.supports_csr(addr)) \
249	    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
250	      HYBRID_M_EXT_CSR_LIST(X)
251	#undef X
252	    }
253	  }
254	
255	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
256	  // L26: guards on the configured scratch GPA so a V drain never stores to a
257	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
258	  void dump_v_to_scratch(uint64_t vlenb)
259	  {
260	    if (scratch_gpa_ == kVScratchGpaUnset)
261	      throw std::runtime_error(
262	        "StateDrain: V state present but scratch GPA unset");
263	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
264	  }
265	
266	  DmiBus& bus_;
267	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
268	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
269	  bool gpr_block_store_ = false;              // opt-in GPR PB sd-sweep drain
270	  bool fpr_block_store_ = false;              // opt-in FPR PB fsd-sweep drain
271	  bool csr_sweep_       = false;              // opt-in Andes+M-ext PB csr sweep
272	};
273	
274	}  // namespace hybrid
