// StateDrain halts the hart via the Debug Module and populates a
// hybrid_state_v1 with the architectural register file. Reuses
// ResumeDriver's DM register constants and DmiBus interface.

#pragma once

#include "hybrid/abstract_command.hpp"
#include "hybrid/andes_caps.hpp"
#include "hybrid/dmi_poll.hpp"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"
#include "hybrid/v_regfile_xfer.hpp"

#include <algorithm>
#include <array>
#include <cstdint>
#include <span>

namespace hybrid
{

class StateDrain
{
public:
  using RD = ResumeDriver;

  // scratch_gpa: the GUEST address of the V-register transport page (L26:
  // the mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the
  // unset sentinel; only the V dump sweep consults it, and it throws there if
  // a V drain is reached with the GPA unset (no silent dump to a bogus
  // address). The simulator passes the real value from platform.main_memory.
  // caps: which Andes custom CSRs the TARGET core implements (from its
  // config.inc, supplied by the sim binary). Defaults to all() so existing
  // call sites are unchanged. Gates the Andes re-read below: reading an
  // unimplemented CSR can stall the DM, same as restoring one.
  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
                      AndesCaps caps = AndesCaps::all())
      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
  {}

  // Opt-in PB block-store (dual of ResumeDriver's set_gpr/fpr_block_load):
  // drain the GPRs/FPRs with a sd/fsd-sweep into the shared scratch page instead
  // of per-register Abstract Command reads. Default OFF; the simulator enables
  // both and lifts the swept bytes with read_{gpr,fpr}_from_scratch. Each is
  // fits-gated in drain_with_passthrough so a full V page falls back to reads.
  void set_gpr_block_store(bool on) { gpr_block_store_ = on; }
  void set_fpr_block_store(bool on) { fpr_block_store_ = on; }

  // Opt-in Andes+M-ext CSR sweep (dual of ResumeDriver::set_csr_sweep): drain
  // the caps-supported CSR block with a Program-Buffer csrr+sd sweep into the CSR
  // scratch page instead of one abstract read per CSR. Off by default; the
  // simulator enables it and lifts the swept values with read_csr_from_scratch.
  void set_csr_sweep(bool on) { csr_sweep_ = on; }

  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
  // drain_with_passthrough when the QEMU 1 snapshot is available.
  auto drain() -> hybrid_state_v1
  {
    hybrid_state_v1 state{};
    state.magic   = HYBRID_STATE_MAGIC;
    state.version = HYBRID_STATE_VERSION;
    state.flags   = HYBRID_FLAG_RV64;
    halt_and_capture_pc_priv(state);

    for (uint16_t i = 1; i < 32; ++i)
      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");

    return state;
  }

  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
  // (L20) so post-vsim FP modifications are captured (otherwise the stale
  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
  // and vreg remain pass-through (read-only / too large for DM).
  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
  // contribution would otherwise be discarded as the passthrough preserves
  // QEMU1's pre-handoff value.
  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
  {
    auto state = input;
    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt

    // GPRs: the dual of the resume block-load. When enabled and the V region
    // leaves room (same fits-gate as the resume side), sd-sweep x1..x30 from the
    // regfile into the scratch page in ~6 round-trips instead of 31 abstract
    // reads; the simulator lifts them with read_gpr_from_scratch. Base x31 is the
    // sweep's pointer -- seeding it destroys its value -- so it is captured here
    // via one abstract read and excluded from the sweep.
    if (gpr_block_store_ && scratch_gpa_ != kVScratchGpaUnset
        && gpr_scratch_fits(input.vlenb)) {
      state.gpr[31] =
        read_register_64(bus_, regno_gpr(31), "StateDrain GPR base");
      pb_block_sweep(bus_, 31, gpr_scratch_gpa(scratch_gpa_), 1, 31, &encode_sd);
    } else {
      for (uint16_t i = 1; i < 32; ++i)
        state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
    }

    if (input.flags & HYBRID_FLAG_FP) {
      // FPRs: fsd-sweep into the scratch page (below the GPR block) when enabled
      // and fits; the simulator lifts f0..f31 with read_fpr_from_scratch. Base x5
      // is a caller-saved GPR already captured above (via the GPR abstract loop
      // or the GPR sweep's scratch), so clobbering it here is safe -- the hart is
      // terminal after drain.
      if (fpr_block_store_ && scratch_gpa_ != kVScratchGpaUnset
          && fpr_scratch_fits(input.vlenb)) {
        pb_block_sweep(bus_, 5, fpr_scratch_gpa(scratch_gpa_), 0, 32, &encode_fsd);
      } else {
        for (uint16_t i = 0; i < 32; ++i)
          state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
      }
      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
    }

    if (input.flags & HYBRID_FLAG_V) {
      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
    }

    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
    // dropped and the stale QEMU1 value passes through into the drained state.
    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));

    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
    // restores them), so re-read them -- an in-ROI write must reach the drained
    // state instead of the stale QEMU1 passthrough value.
    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));

    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));

    // Andes V5 + M-ext CSR block (v3/v4): re-read the transported CSRs so an
    // in-ROI write reaches the drained state instead of the stale QEMU1
    // passthrough (same round-trip as mscratch). When the csr_sweep is enabled
    // this rides a PB csrr+sd sweep into the CSR scratch page (the simulator
    // lifts it via read_csr_from_scratch); else one caps-gated abstract read per
    // CSR. See drain_andes_m_ext.
    drain_andes_m_ext(state);

    // V data regfile: dump v0..v31 to the shared scratch region via the
    // Program Buffer LAST -- after every architectural read above -- so the
    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
    // cannot corrupt the values already captured. The simulator's
    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
    // Stride is HYBRID_VLEN_BYTES_MAX (the wire-format per-register span).
    if (input.flags & HYBRID_FLAG_V)
      dump_v_to_scratch(input.vlenb);

    return state;
  }

  // #1 (drain-minimal): refresh only mcycle/minstret from the hart and pass
  // every other field through from the QEMU1 snapshot. Used when --verify is
  // off: the driver then consumes only the vsim mcycle delta, so the full
  // register-file readback drain_with_passthrough performs (~190 DMI abstract
  // commands -- f0..f31, the V dump sweep, the Andes/M-ext blocks, ...) is pure
  // wasted wall-clock. The hart is left halted, identical to the full drain, so
  // the caller's file-write + exit path is unchanged.
  auto drain_counters_only(const hybrid_state_v1& input) -> hybrid_state_v1
  {
    halt("StateDrain halt (minimal)");

    auto state     = input;
    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle),
                                      "StateDrain mcycle");
    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret),
                                      "StateDrain minstret");
    return state;
  }

private:
  // Debug-Module halt-and-wait, shared by drain() and drain_counters_only():
  // dmactive must transition 0->1 in its own write before haltreq is honored
  // (RISC-V Debug Spec), then wait for allhalted. `ctx` labels the poll.
  void halt(const char* ctx)
  {
    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted, ctx);
  }

  // Halt the hart and capture the two control fields every drain path needs:
  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
  // blocks are filled by the caller, so drain() and drain_with_passthrough
  // share one halt + prologue.
  void halt_and_capture_pc_priv(hybrid_state_v1& state)
  {
    halt("StateDrain halt");
    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
                                  "StateDrain DCSR") & 0x3u;
    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
  }

  // Andes V5 + M-ext CSR drain. When the sweep is enabled and the V region
  // leaves room, batch every caps-supported CSR into the CSR scratch page via a
  // PB csrr+sd sweep (base x6 / value x5 -- both already captured by the GPR
  // drain above, and the hart is terminal, so clobbering them is safe); the
  // simulator lifts the bytes with read_csr_from_scratch. Else one caps-gated
  // abstract read per CSR into state. Same for_each_sweep_csr order + caps gate
  // as the ResumeDriver restore, so the scratch slots agree.
  void drain_andes_m_ext(hybrid_state_v1& state)
  {
    const bool andes = state.flags & HYBRID_FLAG_ANDES;
    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
    if (!andes && !mext) return;

    if (csr_sweep_ && scratch_gpa_ != kVScratchGpaUnset
        && csr_scratch_fits(state.vlenb)) {
      std::array<uint16_t, kCsrScratchSlots> addrs{};
      std::size_t n = 0;
      for_each_sweep_csr(state, caps_,
        [&](std::size_t i, uint16_t addr, uint64_t&) { addrs[i] = addr; n = i + 1; });
      csr_sweep(bus_, /*base=*/6, csr_scratch_gpa(scratch_gpa_), /*val=*/5,
                std::span<const uint16_t>{addrs.data(), n}, CsrSweepDir::Drain);
      return;
    }

    // Fallback: one caps-gated abstract read per CSR into state.
    if (andes) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) \
    state.andes.field = read_register_64(bus_, regno_csr(addr));
      HYBRID_ANDES_CSR_LIST(X)
#undef X
      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
          state.andes.pmacfg[i] =
            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
          state.andes.pmaaddr[i] =
            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
    }
    if (mext) {
#define X(field, addr, name) \
  if (caps_.supports_csr(addr)) \
    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
      HYBRID_M_EXT_CSR_LIST(X)
#undef X
    }
  }

  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
  // L26: guards on the configured scratch GPA so a V drain never stores to a
  // bogus address (mirror of ResumeDriver's reload-sweep guard).
  void dump_v_to_scratch(uint64_t vlenb)
  {
    if (scratch_gpa_ == kVScratchGpaUnset)
      throw std::runtime_error(
        "StateDrain: V state present but scratch GPA unset");
    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
  }

  DmiBus& bus_;
  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
  bool gpr_block_store_ = false;              // opt-in GPR PB sd-sweep drain
  bool fpr_block_store_ = false;              // opt-in FPR PB fsd-sweep drain
  bool csr_sweep_       = false;              // opt-in Andes+M-ext PB csr sweep
};

}  // namespace hybrid

// Andes-CSR capability gating.
//
// A core implements an Andes custom CSR only when the matching feature is
// configured into it (config.inc). Restoring a CSR the target core lacks can
// hang the DMI handshake -- observed on ax45mpv_premium for ucode (no DSP) and
// mecc_code (no ECC). So the resume/drain loops transport only the CSRs the
// target core supports, decided here from the core's feature gates.
//
// This header is Verilator/SystemC-free: it maps a CSR address to its gate and
// answers "does a core with these gates support this CSR". The binding of each
// gate to the core's compiled-in `_NDS_*` config macros lives in the sim binary
// (see andes_caps_from_config), so this stays unit-testable in isolation.
#ifndef ANDES_HYBRID_ANDES_CAPS_HPP
#define ANDES_HYBRID_ANDES_CAPS_HPP

#include <cstdint>
#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace hybrid {

// The hardware feature that gates each transported CSR. ALWAYS = unconditionally
// present (a base machine CSR every core has; never gated off). The first block
// gates the v3 Andes custom CSRs; the second block (UMODE..TRIGGER) gates the v4
// M-ext CSRs (HYBRID_M_EXT_CSR_LIST) -- standard + Andes M-mode CSRs whose
// existence depends on a privilege level or extension the core may not have.
enum class AndesGate : uint8_t {
  ALWAYS = 0,
  DSP,
  CODENSE,
  ZCMT,        // standard Zcmt table jump (jvt); NOT implied by CoDense
  POWERBRAKE,
  STACKSAFE,
  ECC,
  PMA,
  ILM,
  DLM,
  PERF_MONITOR,
  // The Andes PMNDS counter scheme (SPA: mmsc_cfg.PMNDS). RTL ground truth
  // (kv_csr_dec.v existent_csr): these CSRs exist iff PERFORMANCE_MONITOR
  // AND NOT SSCOFPMF -- a core with the standard Sscofpmf count-overflow
  // extension REPLACES the Andes scheme. The _UMODE/_SMODE variants add the
  // privilege term the spec conditions carry (PMNDS & misa[20] / misa[18]).
  PMNDS,        // Andes-scheme perf counters (perf monitor && !Sscofpmf)
  PMNDS_UMODE,  // PMNDS && U-mode
  PMNDS_SMODE,  // PMNDS && S-mode
  ALT_FP,       // umisc_ctl: spec ALT_FP_FMT|CST_CTL, RTL BF16_ARITH|ACE
  // v4 M-ext gates.
  UMODE,       // needs U-mode  (NDS_NUM_PRIVILEGE_LEVELS >= 2)
  SMODE,       // needs S-mode  (NDS_NUM_PRIVILEGE_LEVELS == 3)
  EPMP,        // ePMP / Smepmp (mseccfg)
  SMRNMI,      // resumable NMI (mnscratch/mnepc/mncause/mnstatus/mnvec/mrnxvec)
  EXCSLVL,     // exception save levels (msave*)
  CLIC,        // CLIC / enhanced CLIC (mtvt/mintthresh/mcirq_entry)
  SMSTATEEN,   // state-enable (mstateen0..3)
  CCTL,        // cache control CSRs (mcctlbeginaddr/mcctldata)
  PPI,         // private peripheral interface base (mppib)
  FIO,         // fast IO base (mfiob)
  TRIGGER,     // debug triggers (tselect/tdata1/tdata2/tcontrol/mcontext)
};

// Map an Andes CSR (by address) to the feature gate that enables it. Addresses
// are the HYBRID_ANDES_CSR_LIST scalars plus the PMA block. A CSR with no
// custom-extension gate is ALWAYS (a base machine CSR every Andes core has).
// Maintainer note: a CSR added to HYBRID_ANDES_CSR_LIST that needs gating must
// get a case here, else it defaults to ALWAYS (transported unconditionally).
constexpr AndesGate andes_gate_for(uint16_t csr_addr)
{
  switch (csr_addr) {
    case 0x801: return AndesGate::DSP;           // ucode (DSP overflow flag)
    case 0x800: return AndesGate::CODENSE;        // uitb  (CoDense table base)
    // jvt is Zcmt's table-jump base, NOT part of classic CoDense (exec.it +
    // uitb): a CoDense core without Zcmt faults a csrr of it (seen on
    // ax45mpv_premium, where it aborted the drain CSR sweep).
    case 0x017: return AndesGate::ZCMT;           // jvt   (Zcmt only)
    case 0x7C5: return AndesGate::POWERBRAKE;     // mpft_ctl
    case 0x7C2: return AndesGate::ECC;            // mecc_code
    case 0x7C6:                                   // mhsp_ctl
    case 0x7C7:                                   // msp_bound
    case 0x7C8: return AndesGate::STACKSAFE;      // msp_base
    case 0x7C0: return AndesGate::ILM;            // milmb (ILM base)
    case 0x7C1: return AndesGate::DLM;            // mdlmb (DLM base)
    // v4 M-ext CSR gates (HYBRID_M_EXT_CSR_LIST).
    // The PMNDS counter block (SPA existence: mmsc_cfg.PMNDS, plus misa[20]
    // or misa[18] for the U/S members). Over-claiming any of these faults a
    // PB csrr with cmderr=3, aborting a CSR sweep -- seen live for 0x7D1 on
    // premium (M-only) and 0x7CF on advanced (Sscofpmf replaces PMNDS).
    case 0x7CF: return AndesGate::PMNDS;          // mcounterinten
    case 0x7CE: case 0x7D1: case 0x7D3:           // mcounterwen, mcountermask_m/_u
      return AndesGate::PMNDS_UMODE;
    case 0x7D2: return AndesGate::PMNDS_SMODE;    // mcountermask_s
    case 0x30A: case 0x306:                       // menvcfg, mcounteren
    case 0x808: case 0x80B: case 0x811:           // uzobctl, ucctlbeginaddr, sleepvalue
      return AndesGate::UMODE;
    // umisc_ctl: "Access Mode: User and above" is WHO may touch it, not an
    // existence condition -- spec existence is ALT_FP_FMT | CST_CTL (RTL:
    // BFLOAT16_ARITH | ACE, no privilege term). The UMODE gate under-claimed
    // it on both (M-only) engines; found by the registration audit.
    case 0x813: return AndesGate::ALT_FP;
    case 0x7D5: return AndesGate::SMODE;          // mslideleg
    case 0x747: return AndesGate::EPMP;           // mseccfg
    // The STANDARD counters exist under either perf-monitor scheme (Zihpm);
    // only the Andes PMNDS block above is scheme-dependent.
    case 0x320: case 0xB03: case 0xB04: case 0xB05: case 0xB06:  // mcountinhibit, mhpmcounter3-6
    case 0x323: case 0x324: case 0x325: case 0x326:              // mhpmevent3-6
      return AndesGate::PERF_MONITOR;
    case 0x740: case 0x741: case 0x742: case 0x744:  // mnscratch, mnepc, mncause, mnstatus
    case 0x7DE:                                       // mrnxvec
      return AndesGate::SMRNMI;
    // mnvec is base Andes NMI state -- spec "IM Requirement: Required", RTL
    // decodes it unconditionally on cores that lack Smrnmi entirely. It was
    // wrongly grouped with the Smrnmi CSRs and under-claimed on every engine.
    case 0x7C3:                                   // mnvec
    case 0x7C9: return AndesGate::ALWAYS;         // mdcause (base Andes trap CSR)
    case 0x7D6: case 0x7D7: case 0x7D8: case 0x7D9:  // msavestatus, msaveepc1, msavecause1, msaveepc2
    case 0x7DA: case 0x7DB: case 0x7DC:              // msavecause2, msavedcause1, msavedcause2
      return AndesGate::EXCSLVL;
    case 0x307: case 0x347: case 0x7EC:           // mtvt, mintthresh, mcirq_entry
      return AndesGate::CLIC;
    case 0x30C: case 0x30D: case 0x30E: case 0x30F:  // mstateen0..3
      return AndesGate::SMSTATEEN;
    case 0x7CB: case 0x7CD: return AndesGate::CCTL;  // mcctlbeginaddr, mcctldata
    case 0x7F0: return AndesGate::PPI;            // mppib
    case 0x7F1: return AndesGate::FIO;            // mfiob
    case 0x7A0: case 0x7A1: case 0x7A2: case 0x7A5: case 0x7A8:  // tselect, tdata1, tdata2, tcontrol, mcontext
      return AndesGate::TRIGGER;
    default:
      // PMA cfg (0xBC0, 0xBC2) and addr (0xBD0..0xBDF) blocks.
      if (csr_addr == HYBRID_PMA_CFG0_CSR || csr_addr == HYBRID_PMA_CFG0_CSR + 2)
        return AndesGate::PMA;
      if (csr_addr >= HYBRID_PMA_ADDR0_CSR &&
          csr_addr < HYBRID_PMA_ADDR0_CSR + HYBRID_PMA_ADDR_NUM)
        return AndesGate::PMA;
      return AndesGate::ALWAYS;                    // mxstatus 0x7C4, mclk_ctl 0x7DF
  }
}

// The set of Andes feature gates a target core has on. Built from the core's
// compiled-in config (config.inc) in the sim binary and injected into the
// resume/drain loops, so they transport only the CSRs the core implements.
// Default = every gate on (all(): no gating, the prior unconditional behavior).
struct AndesCaps {
  uint32_t gate_mask = ~0u;

  static constexpr AndesCaps all()  { return AndesCaps{~0u}; }
  static constexpr AndesCaps none() { return AndesCaps{0u}; }

  constexpr void set(AndesGate g, bool on = true)
  {
    const uint32_t bit = 1u << static_cast<unsigned>(g);
    if (on) gate_mask |= bit;
    else    gate_mask &= ~bit;
  }

  constexpr bool gate_on(AndesGate g) const
  {
    return (gate_mask >> static_cast<unsigned>(g)) & 1u;
  }

  // ALWAYS-gated CSRs are present on every core regardless of the mask.
  constexpr bool supports_csr(uint16_t csr_addr) const
  {
    const AndesGate g = andes_gate_for(csr_addr);
    return g == AndesGate::ALWAYS || gate_on(g);
  }
};

// F6: build the caps from the CSR addresses the registered manifest transports,
// instead of from config macros (andes_caps_from_config). The transported set is
// a union of COMPLETE gate-groups -- supports_csr() keys on the gate, so every
// CSR sharing a gate transports together -- hence setting each transported CSR's
// gate reconstructs the EXACT caps. This lets the runtime be driven by the
// measured/registered manifest, making the config->caps model (the andesim
// mirror + parity guard) redundant. Verilator-free, so it stays unit-testable.
inline AndesCaps andes_caps_from_transport_set(const std::vector<uint16_t>& transported)
{
  AndesCaps c = AndesCaps::none();
  for (const uint16_t addr : transported)
    c.set(andes_gate_for(addr), true);
  return c;
}

// The gated CSR names this core supports, for the --describe card. Iterates the
// two single-source-of-truth X-macro lists: the v3 Andes custom CSRs and the v4
// M-ext CSRs. The driver uses this list to gate --verify, so a CSR the core
// lacks is neither restored, drained, nor compared.
inline std::vector<std::string> supported_andes_csr_names(const AndesCaps& caps)
{
  std::vector<std::string> out;
#define X(field, addr, name) if (caps.supports_csr(addr)) out.push_back(name);
  HYBRID_ANDES_CSR_LIST(X)
#undef X
  // PMA group markers (whole pmacfg[]/pmaaddr[] blocks share one gate), so a
  // consumer can include/exclude PMA without listing all 18 entries.
  if (caps.supports_csr(HYBRID_PMA_CFG0_CSR))  out.push_back("pmacfg");
  if (caps.supports_csr(HYBRID_PMA_ADDR0_CSR)) out.push_back("pmaaddr");
  // v4 M-ext CSRs share the same address->gate map and --describe list.
#define X(field, addr, name) if (caps.supports_csr(addr)) out.push_back(name);
  HYBRID_M_EXT_CSR_LIST(X)
#undef X
  return out;
}

}  // namespace hybrid

#endif  // ANDES_HYBRID_ANDES_CAPS_HPP

// Build an AndesCaps from the core's compiled-in config.inc feature macros
// (_NDS_*, supplied by the build-generated cpu_config.hpp). This is the ONE
// place that binds each Andes feature gate to its config macro -- the sim-binary
// counterpart of the Verilator-free andes_caps.hpp, kept separate so the unit
// tests never need the generated header.
//
// PRECONDITION: the _NDS_* macros must already be in scope (include this AFTER
// cpu_config.hpp). A macro that is absent reads as "feature off" (gate clear),
// never a compile error -- so a core whose config omits a knob stays safe.
#pragma once

#include "hybrid/andes_caps.hpp"

namespace hybrid {

inline AndesCaps andes_caps_from_config()
{
  AndesCaps c = AndesCaps::none();

#if defined(_NDS_DSP_SUPPORT_INT) && _NDS_DSP_SUPPORT_INT
  c.set(AndesGate::DSP);           // ucode
#endif
#if defined(_NDS_CODENSE_SUPPORT_INT) && _NDS_CODENSE_SUPPORT_INT
  c.set(AndesGate::CODENSE);       // uitb
#endif
  // Zcmt (jvt): the RTL gates jvt on ZCE_SUPPORT_INT (kv_csr_dec.v); newer
  // config.inc generations carry NDS_ZCE_SUPPORT_INT (advanced: 0), older
  // ones (premium) have no knob at all -- absent reads as "feature off".
#if (defined(_NDS_ZCMT_SUPPORT_INT) && _NDS_ZCMT_SUPPORT_INT) || \
    (defined(_NDS_ZCE_SUPPORT_INT) && _NDS_ZCE_SUPPORT_INT)
  c.set(AndesGate::ZCMT);          // jvt
#endif
#if defined(_NDS_POWERBRAKE_SUPPORT_INT) && _NDS_POWERBRAKE_SUPPORT_INT
  c.set(AndesGate::POWERBRAKE);    // mpft_ctl
#endif
#if defined(_NDS_STACKSAFE_SUPPORT_INT) && _NDS_STACKSAFE_SUPPORT_INT
  c.set(AndesGate::STACKSAFE);     // mhsp_ctl, msp_bound, msp_base
#endif
#if defined(_NDS_PERFORMANCE_MONITOR_INT) && _NDS_PERFORMANCE_MONITOR_INT
  c.set(AndesGate::PERF_MONITOR);  // mcountinhibit, mhpmcounter/event3-6
  // Andes PMNDS scheme (mcounterinten, mcounterwen, mcountermask_*): exists
  // only when the standard Sscofpmf scheme does NOT replace it (RTL:
  // PERFORMANCE_MONITOR_INT==1 & SSCOFPMF_SUPPORT==0), plus the privilege
  // term the SPA conditions carry.
#if !defined(_NDS_SSCOFPMF_SUPPORT) || !_NDS_SSCOFPMF_SUPPORT
  c.set(AndesGate::PMNDS);
#if defined(_NDS_NUM_PRIVILEGE_LEVELS) && (_NDS_NUM_PRIVILEGE_LEVELS >= 2)
  c.set(AndesGate::PMNDS_UMODE);
#endif
#if defined(_NDS_NUM_PRIVILEGE_LEVELS) && (_NDS_NUM_PRIVILEGE_LEVELS >= 3)
  c.set(AndesGate::PMNDS_SMODE);
#endif
#endif
#endif
#if defined(_NDS_PMA_ENTRIES) && (_NDS_PMA_ENTRIES > 0)
  c.set(AndesGate::PMA);           // pmacfg / pmaaddr
#endif
#if defined(_NDS_ILM_SIZE_KB) && (_NDS_ILM_SIZE_KB > 0)
  c.set(AndesGate::ILM);           // milmb
#endif
#if defined(_NDS_DLM_SIZE_KB) && (_NDS_DLM_SIZE_KB > 0)
  c.set(AndesGate::DLM);           // mdlmb
#endif
  // ECC: mecc_code exists if ANY RAM block is configured with ECC.
#if (defined(_NDS_DCACHE_ECC_TYPE_INT) && _NDS_DCACHE_ECC_TYPE_INT) || \
    (defined(_NDS_ICACHE_ECC_TYPE_INT) && _NDS_ICACHE_ECC_TYPE_INT) || \
    (defined(_NDS_ILM_ECC_TYPE_INT)    && _NDS_ILM_ECC_TYPE_INT)    || \
    (defined(_NDS_DLM_ECC_TYPE_INT)    && _NDS_DLM_ECC_TYPE_INT)
  c.set(AndesGate::ECC);           // mecc_code
#endif

  // v4 M-ext gates. Privilege-level gates from NDS_NUM_PRIVILEGE_LEVELS
  // (1 = M, 2 = M+U, 3 = M+S+U). An absent knob reads as off -- safe.
#if defined(_NDS_NUM_PRIVILEGE_LEVELS) && (_NDS_NUM_PRIVILEGE_LEVELS >= 2)
  c.set(AndesGate::UMODE);         // menvcfg, mcounteren, mcountermask_u, U-delta
#endif
#if defined(_NDS_NUM_PRIVILEGE_LEVELS) && (_NDS_NUM_PRIVILEGE_LEVELS >= 3)
  c.set(AndesGate::SMODE);         // mcountermask_s, mslideleg
#endif
#if defined(_NDS_NUM_TRIGGER) && (_NDS_NUM_TRIGGER > 0)
  c.set(AndesGate::TRIGGER);       // tselect, tdata1, tdata2, tcontrol, mcontext
#endif
#if (defined(_NDS_SMEPMP) && _NDS_SMEPMP) || (defined(_NDS_EPMP) && _NDS_EPMP)
  c.set(AndesGate::EPMP);          // mseccfg
#endif
#if (defined(_NDS_SMRNMI) && _NDS_SMRNMI) || (defined(_NDS_RNMI) && _NDS_RNMI)
  c.set(AndesGate::SMRNMI);        // mnscratch/mnepc/mncause/mnstatus/mnvec/mrnxvec
#endif
#if defined(_NDS_EXCSLVL) && (_NDS_EXCSLVL > 0)
  c.set(AndesGate::EXCSLVL);       // msave*
#endif
#if (defined(_NDS_ECLIC) && _NDS_ECLIC) || (defined(_NDS_CLIC) && _NDS_CLIC)
  c.set(AndesGate::CLIC);          // mtvt, mintthresh, mcirq_entry
#endif
#if defined(_NDS_SMSTATEEN) && _NDS_SMSTATEEN
  c.set(AndesGate::SMSTATEEN);     // mstateen0..3
#endif
  // CCTL: the RTL gates the mcctl* CSRs on cache presence (CACHE_SUPPORT_INT
  // -- the spec's mmsc_cfg.CCTLCSR follows the cache RAMs on this family);
  // no config generation emits a dedicated NDS_CCTLCSR knob, so bind the
  // cache sizes too. Found as a live under-claim on both built engines.
#if (defined(_NDS_CCTLCSR) && _NDS_CCTLCSR) || (defined(_NDS_CCTL) && _NDS_CCTL) || \
    (defined(_NDS_ICACHE_SIZE_KB) && (_NDS_ICACHE_SIZE_KB > 0)) || \
    (defined(_NDS_DCACHE_SIZE_KB) && (_NDS_DCACHE_SIZE_KB > 0))
  c.set(AndesGate::CCTL);          // mcctlbeginaddr, mcctldata
#endif
  // umisc_ctl existence: BF16 arithmetic or ACE (spec ALT_FP_FMT | CST_CTL).
#if (defined(_NDS_BFLOAT16_ARITH_SUPPORT) && _NDS_BFLOAT16_ARITH_SUPPORT) || \
    (defined(_NDS_ACE_SUPPORT_INT) && _NDS_ACE_SUPPORT_INT)
  c.set(AndesGate::ALT_FP);        // umisc_ctl
#endif
#if defined(_NDS_PPI_SIZE_KB) && (_NDS_PPI_SIZE_KB > 0)
  c.set(AndesGate::PPI);           // mppib
#endif
#if (defined(_NDS_FIO_SIZE_KB) && (_NDS_FIO_SIZE_KB > 0)) || \
    (defined(_NDS_FIO) && _NDS_FIO)
  c.set(AndesGate::FIO);           // mfiob
#endif

  return c;
}

}  // namespace hybrid

