270	// ---- pb_v_data_sweep batching tests ----------------------------------------
271	// Each Program-Buffer execution is one halted-hart DM round-trip (~1000 sim
272	// cycles in the busy-poll), so the cost is the NUMBER of executions, not the
273	// bytes moved. The sweep batches (transfer; addi) pairs into each execution
274	// and advances the base pointer x7 with the in-buffer addi, so 32 registers
275	// cost ceil(32/7)=5 executions and ONE x7 abstract write -- instead of 32
276	// executions plus 32 per-register x7 writes.
277	
278	namespace {
279	int count_exec_cmds(const RecBus& bus)
280	{
281	    int n = 0;
282	    for (const auto& w : bus.writes)
283	        if (w.reg == kDmiCommand && w.val == kExecProgbufCmd) ++n;
284	    return n;
285	}
286	
287	int count_x7_abstract_writes(const RecBus& bus)
288	{
289	    int n = 0;
290	    for (const auto& w : bus.writes)
291	        if (w.reg == kDmiCommand && (w.val & 0xFFFFu) == regno_gpr(7)
292	            && ((w.val >> 16) & 1u) != 0u)
293	            ++n;
294	    return n;
295	}
296	
297	bool progbuf_holds(const RecBus& bus, uint32_t insn)
298	{
299	    for (const auto& w : bus.writes)
300	        if (w.reg >= kProgbuf0 && w.reg <= kProgbuf0 + kProgbufMaxInsns
301	            && w.val == insn)
302	            return true;
303	    return false;
304	}
305	
306	// Last 64-bit value staged into GPR g via an abstract write: data0/data1 are
307	// the two writes immediately preceding the command that targets regno_gpr(g)
308	// with the write bit set.
309	uint64_t staged_gpr_value(const RecBus& bus, uint16_t g)
310	{
311	    uint64_t v = 0;
312	    for (std::size_t i = 2; i < bus.writes.size(); ++i) {
313	        const auto& w = bus.writes[i];
314	        if (w.reg == kDmiCommand && (w.val & 0xFFFFu) == regno_gpr(g)
315	            && ((w.val >> 16) & 1u) != 0u)
316	            v = (uint64_t(bus.writes[i - 1].val) << 32) | bus.writes[i - 2].val;
317	    }
318	    return v;
319	}
320	}  // namespace
321	
322	TEST_CASE("pb_v_data_sweep: LMUL=8 grouping loads all 32 registers in ONE "
323	          "PB execution from a single staged base")
324	{
325	    RecBus bus;
326	    constexpr uint64_t kScratch = 0x90000000ull;
327	    constexpr uint64_t kVlenb   = 64;          // VLEN=512
328	    constexpr uint64_t kGroup   = 8 * kVlenb;  // 512 bytes per LMUL=8 group
329	
330	    pb_v_data_sweep(bus, kScratch, kVlenb, /*load=*/true);
331	
332	    // 1 vsetvl execution + 1 grouped execution (all 4 groups fit) = 2
333	    // (33 before batching, 6 after addi-batching, 2 with LMUL grouping).
334	    CHECK(count_exec_cmds(bus) == 2);
335	    // Base staged once; the in-buffer addi advances it by one group (8*vlenb).
336	    CHECK(count_x7_abstract_writes(bus) == 1);
337	    CHECK(staged_gpr_value(bus, 7) == kScratch);
338	    CHECK(progbuf_holds(bus, encode_addi(7, 7, int32_t(kGroup))));
339	
340	    // vsetvl operands: AVL=x5=8*vlenb (=VLMAX for m8) and vtype=x6=e8/m8.
341	    CHECK(staged_gpr_value(bus, 5) == kGroup);
342	    CHECK(staged_gpr_value(bus, 6) == kVtypeE8M8);
343	
344	    // Exactly the 4 group bases are loaded (v0, v8, v16, v24); the other 28
345	    // registers ride inside their group, so they are NOT loaded directly.
346	    for (uint8_t g = 0; g < 32; g += 8)
347	        CHECK(progbuf_holds(bus, encode_vle8_v(g, 7)));
348	    CHECK(!progbuf_holds(bus, encode_vle8_v(1, 7)));
349	    CHECK(!progbuf_holds(bus, encode_vle8_v(9, 7)));
350	}
351	
352	TEST_CASE("pb_v_data_sweep: load=false stores the 4 register groups via vse8.v")
353	{
354	    RecBus bus;
355	    pb_v_data_sweep(bus, 0x90000000ull, /*vlenb=*/64, /*load=*/false);
356	
357	    for (uint8_t g = 0; g < 32; g += 8)
358	        CHECK(progbuf_holds(bus, encode_vse8_v(g, 7)));
359	    CHECK(count_exec_cmds(bus) == 2);
360	    CHECK(staged_gpr_value(bus, 6) == kVtypeE8M8);
361	}
362	
363	// ---- csr_sweep behavioral tests --------------------------------------------
364	
365	TEST_CASE("csr_sweep restore: ld+csrrw per CSR, base seeded with the scratch GPA")
366	{
367	    RecBus bus;
368	    bus.read_seq[kDmiAbstractcs] = {8u << 24};  // progbufsize=8 -> 3 CSRs/exec
369	    const std::array<uint16_t, 3> csrs{0x7C4, 0x30A, 0x341};
370	    csr_sweep(bus, /*base=*/6, /*base_gpa=*/0xDEAD0000ull, /*val=*/5,
371	              std::span<const uint16_t>{csrs}, CsrSweepDir::Restore);
372	
373	    for (std::size_t k = 0; k < csrs.size(); ++k) {
374	        CHECK(progbuf_holds(bus, encode_ld(5, 6, int32_t(k * 8))));
375	        CHECK(progbuf_holds(bus, encode_csrrw(0, csrs[k], 5)));
376	    }
377	    CHECK(!progbuf_holds(bus, encode_csrrs(5, 0x7C4, 0)));  // no drain insns leak
378	    CHECK(staged_gpr_value(bus, 6) == 0xDEAD0000ull);       // base seeded once
379	}
380	
381	TEST_CASE("csr_sweep drain: csrr+sd per CSR")
382	{
383	    RecBus bus;
384	    bus.read_seq[kDmiAbstractcs] = {8u << 24};
385	    const std::array<uint16_t, 2> csrs{0x7C4, 0xBD0};
386	    csr_sweep(bus, 6, 0x1000ull, 5, std::span<const uint16_t>{csrs},
387	              CsrSweepDir::Drain);
388	
389	    for (std::size_t k = 0; k < csrs.size(); ++k) {
390	        CHECK(progbuf_holds(bus, encode_csrrs(5, csrs[k], 0)));
391	        CHECK(progbuf_holds(bus, encode_sd(5, 6, int32_t(k * 8))));
392	    }
393	    CHECK(!progbuf_holds(bus, encode_csrrw(0, 0x7C4, 5)));  // no restore insns
394	    CHECK(staged_gpr_value(bus, 6) == 0x1000ull);
395	}
396	
397	TEST_CASE("csr_sweep with an empty list does nothing (no seed, no exec)")
398	{
399	    RecBus bus;
400	    bus.read_seq[kDmiAbstractcs] = {8u << 24};
401	    const std::array<uint16_t, 0> csrs{};
402	    csr_sweep(bus, 6, 0x1000ull, 5, std::span<const uint16_t>{csrs},
403	              CsrSweepDir::Restore);
404	    CHECK(bus.writes.empty());        // early-out before the base seed
405	    CHECK(count_exec_cmds(bus) == 0);
406	}
407	
408	TEST_CASE("csr_sweep: a faulting batch is bisected and the thrown error names "
409	          "the offending CSR")
410	{
411	    // The sweep's contract: every listed CSR is caps-supported, so a cmderr
412	    // means the caps map over-claims one -- a config bug to fix. "cmderr=3"
413	    // alone is undebuggable (the batch hides WHICH csrr faulted), so the
414	    // sweep must re-run the batch one CSR at a time and name the culprit.
415	    RecBus bus;
416	    constexpr uint32_t kCmderr = 0x3u << 8;
417	    // reads: progbufsize, base-seed busy poll,
418	    //        [batch: pre, poll, final=cmderr],
419	    //        [bisect 0x7C4: pre, poll, final=ok],
420	    //        [bisect 0x7A5: pre, poll, final=cmderr]
421	    bus.read_seq[kDmiAbstractcs] = {8u << 24, 0u, 0u, 0u, kCmderr,
422	                                    0u, 0u, 0u, 0u, 0u, kCmderr};
423	    const std::array<uint16_t, 3> csrs{0x7C4, 0x7A5, 0x7DF};
424	
425	    std::string msg;
426	    try {
427	        csr_sweep(bus, 6, 0x1000ull, 5, std::span<const uint16_t>{csrs},
428	                  CsrSweepDir::Drain);
429	    } catch (const std::runtime_error& e) {
430	        msg = e.what();
431	    }
432	    REQUIRE(!msg.empty());
433	    CHECK(msg.find("0x7a5") != std::string::npos);
434	}
435	
436	TEST_CASE("csr_sweep batches at (progbufsize-1)/2 CSRs per execution")
437	{
438	    RecBus bus;
439	    bus.read_seq[kDmiAbstractcs] = {8u << 24};  // 7 usable slots -> 3 CSRs/exec
440	    const std::array<uint16_t, 7> csrs{0x7C4, 0x30A, 0x341, 0x342,
441	                                       0x343, 0x344, 0x345};
442	    csr_sweep(bus, 6, 0x1000ull, 5, std::span<const uint16_t>{csrs},
443	              CsrSweepDir::Restore);
444	    CHECK(count_exec_cmds(bus) == 3);  // 7 CSRs / 3 per exec -> 3+3+1
445	}
